import{_ as r,l as d,o as a,c as i,v as t,p as n,x as o,d as c,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"进程组与会话","description":"","frontmatter":{"title":"进程组与会话","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/process-groups.md","filePath":"cs/process-groups.md","lastUpdated":1789023840000}'),h={name:"cs/process-groups.md"};function m(_,e,B,u,E,P){const s=d("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="进程组与会话" tabindex="-1">进程组与会话 <a class="header-anchor" href="#进程组与会话" aria-label="Permalink to &quot;进程组与会话&quot;">​</a></h1><div class="epigraph"><p>进程组是可以一并发信号的作业；会话把一组进程绑到控制终端，前台组才能读终端。</p><footer>—— 据 Stevens and Rago, Advanced Programming in the UNIX Environment；Tanenbaum MOS 整理</footer></div><p><a href="/cs/exit-reap">上一课</a>让单个 PCB 能干净结束。shell 的 <code>|</code> 与后台 <code>&amp;</code> 要一次管理<strong>多个进程</strong>：Ctrl-C 应打到前台那一组，而不是随机一个 PID。<a href="/cs/signals">信号</a>已能按 PID 投递。缺口是把 PCB 编成<strong>进程组</strong>与<strong>会话</strong>，并与控制终端挂钩。本课只钉这套作业控制对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>管道两端是两个 PID，用户希望「打断这条命令」时两个都停。进程组 ID（PGID）通常等于组长的 PID；<code>kill(-pgid, sig)</code> 打到组内。会话（SID）由会话首领 <code>setsid</code> 创建，脱离旧控制终端，成为守护进程的常见步骤。缺口不是再讲 wait，而是 PCB 上的 pgid/sid 与 tty 的前台组字段。</p><p><span class="marginnote">前台进程组可从终端读；后台组读终端会被 <code>SIGTTIN</code> 停下。这是作业控制，不是新的文件描述符类型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>setpgid</code> 把进程移入某组（受限：须在同一会话）。<code>setsid</code> 创建新会话、新组，切断控制 tty。终端驱动记住前台 PGID；收到中断字符则向该组发 <code>SIGINT</code>。orphan 进程组（组内无成员的父在同一会话）有额外停止信号规则，主干承认「后台作业与 tty 的关系要收口」，不背整章 POSIX。</p>',8)),(a(),n(p,null,{default:o(()=>[l(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SES%5B%22%E4%BC%9A%E8%AF%9D%22%5D%20--%3E%20FG%5B%22%E5%89%8D%E5%8F%B0%E8%BF%9B%E7%A8%8B%E7%BB%84%22%5D%0A%20%20SES%20--%3E%20BG%5B%22%E5%90%8E%E5%8F%B0%E8%BF%9B%E7%A8%8B%E7%BB%84%22%5D%0A%20%20TTY%5B%22%E6%8E%A7%E5%88%B6%E7%BB%88%E7%AB%AF%22%5D%20--%3E%20FG%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>fork 默认继承组与会话；exec 不改。shell 在 fork 之后、exec 之前 <code>setpgid</code>，把管道各段收进同一作业组。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>组把信号从「一个 PCB」抬到「一个作业」。与<a href="/cs/orphan-init">孤儿与 init</a>叠加：会话首领退出可能挂断终端，向该会话发 <code>SIGHUP</code>。调度器仍按线程选 CPU，不按组调度——组不是调度实体。组只影响信号投递与 tty 权限。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 System V 会话与 BSD 作业控制的历史分歧写完，不把 systemd 的 scope 当 OS 原语。窗口系统里的「前台」不是 tty 前台组。线程尚未从进程里拆开：下一课才在同一地址空间挂多条流。</p><p>后课默认：作业是进程组，会话绑 tty。同一份用户页上如何跑多条控制流，下一课讲<a href="/cs/thread-shared-addr">线程与共享地址空间</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>进程组：一并发信号的作业；会话绑控制终端。</li><li>前台组读写 tty；组不是调度实体。</li><li>同地址空间多控制流是下一课线程。</li><li>出处：Stevens and Rago, <em>APUE</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',8))])}const g=r(h,[["render",m]]);export{f as __pageData,g as default};
